    private AppLanguage() {}
    public static synchronized void initialize(Context context) {
        application=context.getApplicationContext(); refresh();
    }
    public static String code(Context context) { return "en".equals(context.getSharedPreferences("persiansocks",0).getString("app-language","fa"))?"en":"fa"; }
    public static Locale locale() { return new Locale(application==null?"fa":code(application)); }
    public static int direction() { return "en".equals(locale().getLanguage())?View.LAYOUT_DIRECTION_LTR:View.LAYOUT_DIRECTION_RTL; }
    public static int gravity() { return direction()==View.LAYOUT_DIRECTION_RTL?android.view.Gravity.RIGHT:android.view.Gravity.LEFT; }
    public static int textDirection() { return direction()==View.LAYOUT_DIRECTION_RTL?View.TEXT_DIRECTION_RTL:View.TEXT_DIRECTION_LTR; }
    public static String isolate(String value) { return "\u2066"+value+"\u2069"; }
    private static Context withLocale(Context context, String code) {
        Configuration config=new Configuration(context.getResources().getConfiguration());
        Locale locale=new Locale(code);config.setLocales(new LocaleList(locale));config.setLayoutDirection(locale);
        return context.createConfigurationContext(config);
    }
    public static Context wrap(Context base) { return withLocale(base,code(base)); }
    public static synchronized void select(Context context,String code) {
        if(!"fa".equals(code)&&!"en".equals(code))throw new IllegalArgumentException("Unsupported language");
        context.getSharedPreferences("persiansocks",0).edit().putString("app-language",code).apply();refresh();
    }
    private static void refresh() {
        localized=wrap(application);
        Context persian=withLocale(application,"fa"),english=withLocale(application,"en");
        LinkedHashMap<String,String> map=new LinkedHashMap<>();
        for(int id:IDS)map.put(persian.getString(id),english.getString(id));
        ArrayList<String> keys=new ArrayList<>();for(String key:map.keySet())if(key.matches("(?s).*[\\u0600-\\u06ff].*"))keys.add(key);keys.sort((a,b)->Integer.compare(b.length(),a.length()));
        orderedKeys=Collections.unmodifiableList(keys);translations=Collections.unmodifiableMap(map);
    }
    public static String t(int id) { return localized.getString(id); }
    public static String display(CharSequence input) {
        if(input==null)return "";String value=input.toString();
        if(!"en".equals(locale().getLanguage()))return value;
        boolean persian=false;for(int i=0;i<value.length();i++)if(value.charAt(i)>=0x0600&&value.charAt(i)<=0x06ff){persian=true;break;}
        if(!persian)return value;
        String exact=translations.get(value);if(exact!=null)return exact;
        // Dynamic messages are composed of UI fragments plus numbers; replace Persian fragments only.
        for(String key:orderedKeys)value=value.replace(key,translations.get(key));
        return value;
    }
    public static String version(Context context) {
        try { return context.getPackageManager().getPackageInfo(context.getPackageName(),0).versionName; }
        catch(Exception ex) { return "?"; }
    }
